<script setup lang="ts">
/* A tool page generated by the server (/pivot: a whole HTML page with their own scripts) in a sandboxed frame.
   The page is fetched with the user's token and handed over as srcdoc. The sandbox never allows same-origin: the
   frame's scripts reach neither the session nor the API (tests/test_untrusted_output.py checks OutilsPage.vue). */
import { inject, ref, watch } from "vue";
import { API_KEY } from "../../lib/api";

const props = defineProps<{ url: string; sandbox: string; title: string; loading: string; testid: string }>();

const api = inject(API_KEY)!;
const html = ref("");
const status = ref<"loading" | "ready" | "error">("loading");
const message = ref("");
let request = 0;

async function load(): Promise<void> {
  const mine = ++request; // a slower answer for a former url is dropped
  status.value = "loading";
  try {
    const res = await api(props.url);
    if (mine !== request) {
      return;
    }
    if (!res.ok) {
      message.value = `❌ Erreur lors du chargement (HTTP ${res.status}).`;
      status.value = "error";
      return;
    }
    const text = await res.text();
    if (mine !== request) {
      return;
    }
    html.value = text;
    status.value = "ready";
  } catch {
    if (mine !== request) {
      return;
    }
    message.value = "❌ Serveur injoignable : vérifiez la connexion réseau.";
    status.value = "error";
  }
}

watch(() => props.url, load, { immediate: true });
defineExpose({ reload: load });
</script>

<template>
  <div
    v-if="status !== 'ready'"
    :data-testid="`${testid}-status`"
    :class="[
      'flex min-h-40 items-center justify-center rounded-xl border border-slate-200 bg-white p-6 text-[13px]',
      status === 'error' ? 'text-red-600' : 'text-slate-500',
    ]"
  >
    {{ status === "loading" ? `⏳ ${loading}` : message }}
  </div>
  <iframe
    v-show="status === 'ready'"
    :data-testid="testid"
    :srcdoc="html"
    :sandbox="sandbox"
    :title="title"
    class="h-[calc(100dvh-14rem)] min-h-[420px] w-full rounded-xl border border-slate-200 bg-white"
  />
</template>
